impl Effect {
    /// The workshop extension this effect requires, if any.
    pub fn extension(self) -> Option<Extension> {
        match self {
            Self::EchoFocusingBeamSound
            | Self::JunkratTrapChainSound
            | Self::MercyBoostBeamSound
            | Self::MercyHealBeamSound
            | Self::MoiraCoalescenceSound
            | Self::MoiraGraspConnectedSound
            | Self::MoiraOrbDamageSound
            | Self::MoiraOrbHealSound
            | Self::OmnicSlicerBeamSound
            | Self::OrisaAmplifierSound
            | Self::OrisaHaltTendrilSound
            | Self::SymmetraProjectorSound
            | Self::WinstonTeslaCannonSound
            | Self::ZaryaParticleBeamSound => Some(Extension::BeamSounds),
            Self::AnaNanoBoostedSound
            | Self::BaptisteImmortalityFieldProtectedSound
            | Self::EchoCloningSound
            | Self::LucioSoundBarrierProtectedSound
            | Self::MeiFrozenSound
            | Self::MercyDamageBoostedSound
            | Self::SigmaGraviticFluxTargetSound
            | Self::SombraHackedSound
            | Self::SombraHackingSound
            | Self::TorbjornOverloadingSound
            | Self::WidowmakerVenomMineTargetSound
            | Self::WinstonPrimalRageSound
            | Self::WinstonTeslaCannonTargetSound
            | Self::WreckingBallAdaptiveShieldTargetSound
            | Self::WreckingBallPiledriverFireSound
            | Self::ZenyattaOrbOfDiscordTargetSound => {
                Some(Extension::BuffAndDebuffSounds)
            }
            Self::AnaBioticGrenadeIncreasedHealing
            | Self::AnaNanoBoosted
            | Self::BaptisteImmortalityFieldProtected
            | Self::EchoCloning
            | Self::HealTarget
            | Self::HealTargetActive
            | Self::LucioSoundBarrierProtected
            | Self::MercyDamageBoosted
            | Self::ReaperWraithForm
            | Self::SoldierSprinting
            | Self::TorbjornOverloading
            | Self::WinstonPrimalRage
            | Self::WreckingBallAdaptiveShieldTarget
            | Self::WreckingBallPiledriverFire => Some(Extension::BuffStatusEffects),
            Self::AnaBioticGrenadeNoHealing
            | Self::AnaSleeping
            | Self::AsheDynamiteBurningMaterial
            | Self::AsheDynamiteBurningParticle
            | Self::CassidyFlashbangStunned
            | Self::MeiFrozen
            | Self::SigmaGraviticFluxTarget
            | Self::SombraHackedLooping
            | Self::WidowmakerVenomMineTarget
            | Self::WinstonTeslaCannonTarget
            | Self::ZenyattaOrbOfDiscordTarget => Some(Extension::DebuffStatusEffects),
            _ => None,
        }
    }
}
